// Only the selected RIVAL_03 native battle presentation/engine wait. Never persistence.
export async function waitNativeHarinBattle(play,signal){if(!(signal instanceof AbortSignal))throw Error('INVALID_HARIN_LIFECYCLE');const cancelled=()=>Object.assign(Error('HARIN_NATIVE_DISPOSED'),{code:'HARIN_NATIVE_DISPOSED'});if(signal.aborted)throw cancelled();let cancel;try{return await new Promise((resolve,reject)=>{cancel=()=>reject(cancelled());signal.addEventListener('abort',cancel,{once:true});Promise.resolve().then(()=>{if(signal.aborted)throw cancelled();return play()}).then(resolve,reject)})}finally{signal.removeEventListener('abort',cancel)}}
